/**
 * GET /api/unsubscribe?token=<signed-token>
 *
 * Handles one-click unsubscribe links embedded in newsletter emails.
 * The token is an HMAC-SHA256 signed payload: base64url(JSON({email, exp})).sig
 * Generated by newsletter-engine.ts at send-time per subscriber.
 *
 * On success: sets status='unsubscribed' in Supabase, redirects to /unsubscribe?success=1
 * On failure: redirects to /unsubscribe?error=1
 *
 * Token generation/verification logic lives in src/lib/unsubscribe.ts —
 * Next.js App Router forbids non-handler named exports from route.ts files.
 */

import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase';
import { ENV } from '@/lib/env';
import { verifyUnsubscribeToken } from '@/lib/unsubscribe';

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const token = searchParams.get('token') || '';

  const siteUrl = ENV.SITE_URL;
  const errorUrl = `${siteUrl}/unsubscribe?error=1`;

  if (!token) {
    return NextResponse.redirect(errorUrl);
  }

  const email = verifyUnsubscribeToken(token);
  if (!email) {
    return NextResponse.redirect(errorUrl);
  }

  // Safe GET: Do NOT mutate DB on GET. Redirect to the confirmation page.
  // This prevents mail scanners, preview bots, and prefetch engines from silently unsubscribing users.
  const confirmUrl = `${siteUrl}/unsubscribe?token=${encodeURIComponent(token)}&confirm=1`;
  return NextResponse.redirect(confirmUrl);
}

// Support POST for both RFC 8058 one-click List-Unsubscribe-Post and browser confirmation form
export async function POST(req: NextRequest) {
  const siteUrl = ENV.SITE_URL;
  const errorUrl = `${siteUrl}/unsubscribe?error=1`;
  const successUrl = `${siteUrl}/unsubscribe?success=1`;

  let token = req.nextUrl.searchParams.get('token') || '';
  let isOneClick = req.nextUrl.searchParams.get('List-Unsubscribe') === 'One-Click';

  const contentType = req.headers.get('content-type') || '';
  const acceptHeader = req.headers.get('accept') || '';

  if (contentType.includes('application/x-www-form-urlencoded')) {
    try {
      const clonedReq = req.clone();
      const rawText = await clonedReq.text();
      if (rawText.includes('List-Unsubscribe=One-Click')) {
        isOneClick = true;
      }
      const formData = await req.formData();
      if (!token) token = (formData.get('token') as string) || '';
      if (formData.get('List-Unsubscribe') === 'One-Click') {
        isOneClick = true;
      }
    } catch {
      // ignore form parsing error
    }
  } else if (!token && contentType.includes('application/json')) {
    try {
      const body = await req.json();
      token = body?.token || '';
      if (body?.['List-Unsubscribe'] === 'One-Click') isOneClick = true;
    } catch {
      // ignore json parsing error
    }
  }

  // A browser form submission is when the client explicitly asks for an HTML document
  // AND is not an RFC 8058 automated one-click client.
  const isBrowserForm = !isOneClick && acceptHeader.includes('text/html');

  if (!token) {
    if (isBrowserForm) return NextResponse.redirect(errorUrl, { status: 303 });
    return NextResponse.json({ error: 'Token required' }, { status: 400 });
  }

  const email = verifyUnsubscribeToken(token);
  if (!email) {
    if (isBrowserForm) return NextResponse.redirect(errorUrl, { status: 303 });
    return NextResponse.json({ error: 'Invalid or expired token' }, { status: 400 });
  }

  if (!supabaseAdmin) {
    if (isBrowserForm) return NextResponse.redirect(errorUrl, { status: 303 });
    return NextResponse.json({ error: 'Database unavailable' }, { status: 503 });
  }

  const { error } = await supabaseAdmin
    .from('newsletter_subscribers')
    .update({ status: 'unsubscribed', updated_at: new Date().toISOString() })
    .eq('email', email.toLowerCase().trim());

  if (error) {
    console.error('[Unsubscribe] DB error:', error.message);
    if (isBrowserForm) return NextResponse.redirect(errorUrl, { status: 303 });
    return NextResponse.json({ error: 'Failed to update subscription status' }, { status: 500 });
  }

  console.log('[Unsubscribe] Successfully unsubscribed recipient');

  if (isBrowserForm) {
    return NextResponse.redirect(successUrl, { status: 303 });
  }

  // RFC 8058 one-click and API clients expect a 200 response
  return new NextResponse(null, { status: 200 });
}
